package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.TokenRedefinicaoDAO;import br.edu.ifms.robotica.seguranca.SenhaUtil;
@WebServlet("/redefinir-senha") public class RedefinirSenhaServlet extends HttpServlet{private final TokenRedefinicaoDAO dao=new TokenRedefinicaoDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{p.setHeader("Cache-Control","no-store");String token=r.getParameter("token");try{if(token==null||dao.buscarValido(token)==null)r.setAttribute("tokenInvalido",true);else r.setAttribute("token",token);r.getRequestDispatcher("/WEB-INF/views/public/redefinir-senha.jsp").forward(r,p);}catch(SQLException e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String token=r.getParameter("token"),senha=r.getParameter("novaSenha");try{if(senha==null||!senha.equals(r.getParameter("confirmacao")))throw new IllegalArgumentException("erro.senha.confirmacao");String hash=SenhaUtil.gerarHash(senha);dao.redefinir(token,hash);p.sendRedirect(r.getContextPath()+"/login?sucesso=senha");}catch(IllegalArgumentException e){r.setAttribute("erro",e.getMessage());r.setAttribute("token",token);r.getRequestDispatcher("/WEB-INF/views/public/redefinir-senha.jsp").forward(r,p);}catch(SQLException e){r.setAttribute("tokenInvalido",true);r.getRequestDispatcher("/WEB-INF/views/public/redefinir-senha.jsp").forward(r,p);}}
}
